class _FinanceScreenState extends State<FinanceScreen>{List<MoneyTransaction> items=[];DateTime month=DateTime(DateTime.now().year,DateTime.now().month);bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{items=(await StorageService.read('finance')).map(MoneyTransaction.fromJson).toList();final now=DateTime.now();for(final x in items){final d=DateTime.tryParse(x.dueDate);if(d!=null&&!x.isPaid&&!x.isCancelled&&d.isBefore(DateTime(now.year,now.month,now.day))){x.paymentStatus='overdue';}}if(mounted)setState(()=>loading=false);}Future<void> _save()=>StorageService.write('finance',items.map((e)=>e.toJson()).toList());String _money(double v)=>'R\$ ${v.toStringAsFixed(2).replaceAll('.',',')}';String money(double v)=>_money(v);List<MoneyTransaction> _month(DateTime d)=>items.where((x)=>x.date.startsWith(DateFormat('yyyy-MM').format(d))&&!x.isCancelled).toList();double _sum(Iterable<MoneyTransaction> xs,bool income,{bool paid=false})=>xs.where((x)=>x.income==income&&(!paid||x.isPaid)).fold<double>(0,(a,x)=>a+x.amount);double _balance()=>items.where((x)=>x.isPaid&&!x.isCancelled).fold<double>(0,(a,x)=>a+(x.income?x.amount:-x.amount));Future<void> _single(bool income)async{final d=TextEditingController(),a=TextEditingController();String cat=income?'Salário':'Outros';String status='paid';final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:Text(income?'Nova entrada':'Nova despesa'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:d,decoration:const InputDecoration(labelText:'Descrição')),TextField(controller:a,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Valor')),DropdownButtonFormField<String>(initialValue:cat,items:(income?incomeCategories:expenseCategories).map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v){if(v!=null)cat=v;},decoration:const InputDecoration(labelText:'Categoria')),if(!income)DropdownButtonFormField<String>(initialValue:status,items:const[DropdownMenuItem(value:'paid',child:Text('Pago')),DropdownMenuItem(value:'pending',child:Text('Previsto'))],onChanged:(v){if(v!=null)status=v;},decoration:const InputDecoration(labelText:'Status'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Salvar'))]));final v=double.tryParse(a.text.replaceAll(',','.'));final description=d.text.trim();d.dispose();a.dispose();if(ok!=true||v==null||v<=0||description.isEmpty)return;final date=DateFormat('yyyy-MM-dd').format(DateTime.now());items.add(MoneyTransaction(id:DateTime.now().microsecondsSinceEpoch.toString(),date:date,description:description,category:cat,amount:v,income:income,paymentStatus:income?'paid':status,dueDate:date,paidDate:status=='paid'?date:null));await _save();if(mounted)setState((){});}
