Future<void> _toggle(MoneyTransaction x)async{x.paymentStatus=x.isPaid?'pending':'paid';x.paidDate=x.isPaid?null:DateFormat('yyyy-MM-dd').format(DateTime.now());await _save();if(mounted)setState((){});}Future<void> _remove(MoneyTransaction x)async{items.removeWhere((e)=>e.id==x.id);await _save();if(mounted)setState((){});}
@override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final cur=_month(month);final inc=_sum(cur,true,paid:true),out=_sum(cur,false,paid:true);final cats=<String,double>{};for(final x in cur.where((x)=>!x.income)){cats[x.category]=(cats[x.category]??0)+x.amount;}final months=List.generate(6,(i)=>DateTime(month.year,month.month-5+i));return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Financeiro',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_menu,icon:const Icon(Icons.add),label:const Text('Adicionar'))]),AppCard(child:Row(children:[IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month-1)),icon:const Icon(Icons.chevron_left)),Expanded(child:Text(DateFormat('MMMM yyyy','pt_BR').format(month),textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.bold))),IconButton(onPressed:()=>setState(()=>month=DateTime(month.year,month.month+1)),icon:const Icon(Icons.chevron_right))])),Row(children:[Expanded(child:_metric('Entradas realizadas',inc)),Expanded(child:_metric('Despesas realizadas',out))]),Row(children:[Expanded(child:_metric('Saldo atual',_balance())),Expanded(child:_metric('Resultado do mês',inc-out))]),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Previsão e compromissos',style:Theme.of(context).textTheme.titleLarge),Text('Comprometido: ${money(cur.where((x)=>!x.income&&!x.isPaid).fold<double>(0,(a,x)=>a+x.amount))}'),Text('Saldo projetado: ${money(_sum(cur,true)-_sum(cur,false))}')])),AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Entradas x despesas — 6 meses',style:Theme.of(context).textTheme.titleLarge),SizedBox(height:180,child:CustomPaint(painter:_FinanceChart(months,items,Theme.of(context).colorScheme.primary),child:const SizedBox.expand()))])),if(cats.isNotEmpty)AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Despesas por categoria',style:Theme.of(context).textTheme.titleLarge),for(final e in cats.entries)_category(e.key,e.value,cats.values.fold<double>(0,(a,b)=>a+b))])),const SizedBox(height:8),Text('Movimentações',style:Theme.of(context).textTheme.titleLarge),if(cur.isEmpty)const AppCard(child:Text('Nenhuma movimentação neste mês.')),for(final x in cur)_movement(x)]));}
Widget _metric(String l,double v)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(_money(v),style:const TextStyle(fontWeight:FontWeight.bold)),Text(l,style:Theme.of(context).textTheme.bodySmall)]));Widget _category(String n,double v,double total)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(n),Text(_money(v))]),LinearProgressIndicator(value:total==0?0:v/total)]));Widget _movement(MoneyTransaction x)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(x.description),subtitle:Text('${x.category} • ${x.paymentStatus}${x.isInstallment?' • ${x.installmentNumber}/${x.totalInstallments}':''}${x.isRecurring?' • recorrente':''}'),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='pay')_toggle(x);if(v=='delete')_remove(x);},itemBuilder:(_)=>const[PopupMenuItem(value:'pay',child:Text('Marcar pago/previsto')),PopupMenuItem(value:'delete',child:Text('Excluir'))])));}
class _FinanceChart extends CustomPainter{final List<DateTime> months;final List<MoneyTransaction> items;final Color color;_FinanceChart(this.months,this.items,this.color);@override void paint(Canvas c,Size s){final inc=<double>[],out=<double>[];for(final m in months){final k=DateFormat('yyyy-MM').format(m);inc.add(items.where((x)=>x.date.startsWith(k)&&x.income&&x.isPaid&&!x.isCancelled).fold<double>(0,(a,x)=>a+x.amount));out.add(items.where((x)=>x.date.startsWith(k)&&!x.income&&x.isPaid&&!x.isCancelled).fold<double>(0,(a,x)=>a+x.amount));}final maxV=[...inc,...out].fold<double>(0,(a,b)=>a>b?a:b);final range=maxV<=0?1.0:maxV;final p1=Paint()..color=color..strokeWidth=3..style=PaintingStyle.stroke;final p2=Paint()..color=Colors.grey..strokeWidth=3..style=PaintingStyle.stroke;void line(List<double> values,Paint p){final path=Path();for(var i=0;i<values.length;i++){final x=values.length==1?s.width/2:i*s.width/(values.length-1);final y=s.height-20-values[i]/range*(s.height-45);if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}c.drawPath(path,p);}line(inc,p1);line(out,p2);}@override bool shouldRepaint(covariant _FinanceChart old)=>old.months!=months||old.items!=items||old.color!=color;}
